// Holding registers 0..11 from the ChinarSoft virtual machine -> one object
const r = msg.payload;
const STATES  = ['STOPPED', 'RUNNING', 'IDLE', 'FAULT', 'CHANGEOVER', 'PLANNED_STOP'];
const REASONS = ['-', 'material shortage', 'jam', 'motor overload', 'sensor fault',
                 'changeover', 'break/meal', 'planned maintenance'];

msg.payload = {
    state:      STATES[r[0]] ?? `UNKNOWN(${r[0]})`,
    reason:     REASONS[r[1]] ?? String(r[1]),
    good:       r[2] * 65536 + r[3],      // 32-bit counter, high word first
    scrap:      r[4] * 65536 + r[5],
    idealCycle: r[6] / 10,                // seconds
    cycle:      r[7] / 10,                // seconds
    product:    r[8],
    temp:       r[9] / 10,                // degC
    heartbeat:  r[10],                    // +1 per machine second
    inState:    r[11]                     // machine seconds in current state
};
return msg;

// Detects every state change and turns each finished stop into one record.
// Time comes from the machine's own heartbeat (+1 per machine second),
// so durations stay correct at any simulator --speed.
const p = msg.payload;
const PLANNED = ['CHANGEOVER', 'PLANNED_STOP'];
const bucket = s => s === 'RUNNING' ? 'run' : PLANNED.includes(s) ? 'planned' : 'unplanned';

let last   = context.get('last');
let clock  = context.get('clock')  || 0;                    // machine seconds
let totals = context.get('totals') || { run: 0, planned: 0, unplanned: 0 };
let log    = context.get('log')    || [];

const add = {};                                             // machine seconds per bucket in this reading
const credit = (b, sec) => { totals[b] += sec; add[b] = (add[b] || 0) + sec; };
if (!last) {                                                // first reading
    const r = flow.get('restore');                          // what InfluxDB already knew
    if (r === undefined) return null;                       // wait until the restore query answered
    clock = p.heartbeat;
    last  = { state: p.state, reason: p.reason, since: clock - p.inState };
    if (r && r.heartbeat !== undefined) {                   // Node-RED restarted mid-shift
        totals = { ...totals, ...r.totals };
        log    = r.log;
        const gap  = (p.heartbeat - r.heartbeat + 65536) % 65536;   // machine seconds we missed
        const here = Math.min(gap, p.inState);              // current state: the machine tells us
        credit(bucket(p.state), here);
        // the rest of the gap: the part counter tells us how much of it was running
        let parts = (p.good + p.scrap) - r.parts;
        if (p.state === 'RUNNING') parts -= here / p.cycle;
        const rest = gap - here;
        const run  = Math.min(rest, Math.max(0, parts) * r.cycle);
        if (run > 0) credit('run', Math.round(run));
        const left = rest - Math.round(run);                // stopped, but we didn't see why
        if (left > 0) credit(r.bucket === 'run' ? 'unplanned' : r.bucket, left);
    } else {                                                // fresh start
        credit(bucket(p.state), p.inState);
    }
} else {
    const dt = (p.heartbeat - last.hb + 65536) % 65536;     // heartbeat wraps at 65535
    clock += dt;
    credit(bucket(last.state), dt);
}

const hhmm = s => String(Math.floor(s / 3600)).padStart(2, '0') + ':' +
                  String(Math.floor(s / 60) % 60).padStart(2, '0');
let stop = null;

if (p.state !== last.state) {
    if (last.state !== 'RUNNING') {                          // a stop just ended
        stop = { payload: {
            start:   hhmm(last.since),
            end:     hhmm(clock),
            minutes: Math.round((clock - last.since) / 6) / 10,
            state:   last.state,
            reason:  last.reason,
            type:    bucket(last.state)
        }};
        log = [stop.payload, ...log].slice(0, 50);           // newest first
    }
    last = { state: p.state, reason: p.reason, since: clock };
}
last.hb = p.heartbeat;

context.set('last', last);
context.set('clock', clock);
context.set('totals', totals);
context.set('log', log);

const live = { payload: { ...p, clock: hhmm(clock), add, totals: {
    run:       Math.round(totals.run / 60),
    planned:   Math.round(totals.planned / 60),
    unplanned: Math.round(totals.unplanned / 60)
}}};
return [live, stop, stop ? { payload: log } : null];

// One CSV line per stop; writes the header once when the file is new.
const s = msg.payload;
const file = env.get('STOPS_FILE') || 'stops.csv';
let line = [s.start, s.end, s.minutes, s.state, s.reason, s.type].join(',');
if (!fs.existsSync(file)) line = 'start,end,minutes,state,reason,type\n' + line;
msg.filename = file;
msg.payload = line;
return msg;

// Every reading -> InfluxDB line protocol:  measurement,tags fields timestamp
// dt = machine seconds since the last reading, tagged with the bucket they belong to
const p = msg.payload;
const ts = Date.now();
const lines = Object.entries(p.add).map(([bucket, dt]) =>
    `machine,line=packaging,bucket=${bucket} ` +
    `state="${p.state}",reason="${p.reason}",good=${p.good}i,scrap=${p.scrap}i,` +
    `cycle=${p.cycle},temp=${p.temp},dt=${dt}i,heartbeat=${p.heartbeat}i ${ts}`);
if (!lines.length) return null;
msg.payload = lines.join('\n');
return msg;

// Every finished stop -> one line in the 'stops' table
const s = msg.payload;
const esc = t => String(t).replace(/[ ,=]/g, m => '\\' + m);
msg.payload =
    `stops,line=packaging,type=${s.type},state=${s.state},reason=${esc(s.reason)} ` +
    `minutes=${s.minutes},started="${s.start}",ended="${s.end}" ` +
    Date.now();
return msg;

// POST line protocol to InfluxDB 3 Core
msg.method  = 'POST';
msg.url     = `${env.get('INFLUX_URL') || 'http://127.0.0.1:8181'}/api/v3/write_lp?db=factory&precision=ms`;
msg.headers = { 'Authorization': 'Bearer ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'text/plain' };
return msg;

// On start: ask InfluxDB what it already knows about this shift (last 8 hours)
const base = env.get('INFLUX_URL') || 'http://127.0.0.1:8181';
const headers = { 'Authorization': 'Bearer ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'application/json' };
const q = sql => ({ method: 'POST', url: `${base}/api/v3/query_sql`, headers,
                    payload: { db: 'factory', q: sql, format: 'json' } });
flow.set('restore', undefined);
return [
  { ...q(`SELECT bucket, SUM(dt) AS seconds FROM machine
           WHERE time > now() - INTERVAL '8 hours' GROUP BY bucket`), topic: 'totals' },
  { ...q(`SELECT bucket, heartbeat, good, scrap, cycle FROM machine
           WHERE time > now() - INTERVAL '8 hours' ORDER BY time DESC LIMIT 1`), topic: 'last' },
  { ...q(`SELECT started, ended, minutes, state, reason, type FROM stops
           WHERE time > now() - INTERVAL '8 hours' ORDER BY time DESC LIMIT 50`), topic: 'log' }
];

// Collect the three answers, then hand them to 'Detect stops'
const got = context.get('got') || {};
const ok  = msg.statusCode === 200 && Array.isArray(msg.payload);
got[msg.topic] = ok ? msg.payload : [];
if (!ok) node.warn(`InfluxDB ${msg.topic}: ${msg.statusCode} – starting from zero`);
if (Object.keys(got).length < 3) { context.set('got', got); return null; }
context.set('got', {});

if (!got.last.length) {                                   // nothing stored yet
    flow.set('restore', false);           // false = nothing to restore (null would delete the key)
    node.status({ fill: 'grey', shape: 'dot', text: 'fresh start' });
    return null;
}
const totals = { run: 0, planned: 0, unplanned: 0 };
got.totals.forEach(r => totals[r.bucket] = Number(r.seconds));
const log = got.log.map(r => ({ start: r.started, end: r.ended, minutes: r.minutes,
                                state: r.state, reason: r.reason, type: r.type }));
const L = got.last[0];
flow.set('restore', { totals, log, heartbeat: Number(L.heartbeat), bucket: L.bucket,
                      parts: Number(L.good) + Number(L.scrap), cycle: Number(L.cycle) || 2 });
node.status({ fill: 'green', shape: 'dot',
              text: `restored ${Math.round((totals.run + totals.planned + totals.unplanned) / 60)} min, ${log.length} stops` });
return { payload: log };
